// This example shows how to subscribe to multiple input topics.
//
// NOTE:
// User Scripts can subscribe to multiple input topics, but can only publish on a single topic.

import { Input, Header, Pose } from "./types";
import { MessageTypeBySchemaName } from "./generatedTypes";

type Path = MessageTypeBySchemaName["nav_msgs/Path"];

type Output = {
  header: MessageTypeBySchemaName["std_msgs/Header"];
  poses: MessageTypeBySchemaName["geometry_msgs/PoseStamped"][];
};
type GlobalVariables = { id: number };

// List all the input topics in the `input` array
export const inputs = ["/viz/trajectory/raceline"];
export const output = "/userscripts/viz/trajectory/raceline";

// Make an InputEvent type alias. Since our script will get a message from either input topic, we need to enumerate the topics.
type InputEvent = Input<"/viz/trajectory/raceline">;

// Function to process a single message
function processMessage(message: any) {
  // Check if the message has a frame_id field and if it is an empty string
  if (message.header.frame_id === "") {
    // Set frame_id to "world"
    message.header.frame_id = "world";
  }
  // If the message has sub-messages, process them recursively
  if (Array.isArray(message.poses)) {
    message.poses = message.poses.map(processMessage);
  }
  // Return the modified message
  return message;
}

export default function script(
  event: InputEvent,
  globalVars: GlobalVariables,
): Path {
  return processMessage(event.message);
}

