import { Input, Message } from "./types";
import { buildRosMarker, MarkerTypes } from "./markers";

type GlobalVariables = {
  steering: number;
};

export const inputs = ["/slam/vehicle_state", "/sensor/steering"];
export const output = "/userscripts/slam/vehicle_state";

type Marker = Message<"visualization_msgs/Marker">;
type MarkerArray = Message<"visualization_msgs/MarkerArray">;

// === VEHICLE PARAMS (TUNE THESE) ===
const LIDAR_X_POSITION = 0.75;
const WHEELBASE = 1.525;
const TRACK = 1.0;

const LIDAR_TO_REAR_AXLE = 1.7; // tune this

const OFFSETS = {
  rear: { x: -LIDAR_TO_REAR_AXLE, y: 0 },
  fl:   { x: -LIDAR_TO_REAR_AXLE + WHEELBASE, y: TRACK / 2 },
  fr:   { x: -LIDAR_TO_REAR_AXLE + WHEELBASE, y: -TRACK / 2 },
};

// meshes
const MESH = {
  monocoque: "package://as_utilities_pkg/models/20D_main.stl",
  rear: "package://as_utilities_pkg/models/20D_wheel_rear_r_l.stl",
  fl: "package://as_utilities_pkg/models/20D_wheel_front_l.stl",
  fr: "package://as_utilities_pkg/models/20D_wheel_front_r.stl",
};

function yawToQuat(yaw: number) {
  return {
    x: 0,
    y: 0,
    z: Math.sin(yaw / 2),
    w: Math.cos(yaw / 2),
  };
}

function rotate2D(x: number, y: number, yaw: number) {
  return {
    x: Math.cos(yaw) * x - Math.sin(yaw) * y,
    y: Math.sin(yaw) * x + Math.cos(yaw) * y,
  };
}

function applyOffset(x: number, y: number, yaw: number) {
  const offsetLocal = [-LIDAR_X_POSITION, 0];
  const rot = rotate2D(offsetLocal[0], offsetLocal[1], yaw);
  return { x: x + rot.x, y: y + rot.y };
}

// === ACKERMANN ===
function computeAckermann(steering: number) {
  if (Math.abs(steering) < 1e-6) {
    return { left: 0, right: 0 };
  }

  const R = WHEELBASE / Math.tan(steering);

  return {
    left: Math.atan(WHEELBASE / (R - TRACK / 2)),
    right: Math.atan(WHEELBASE / (R + TRACK / 2)),
  };
}

export default function slam_vis(
  event: Input<"/slam/vehicle_state"> | Input<"/sensor/steering">,
  globalVars: GlobalVariables,
): MarkerArray | undefined {
  // store steering
  if (event.topic === "/sensor/steering") {
    globalVars.steering = event.message.data ?? 0;
    return;
  }

  if (event.topic !== "/slam/vehicle_state") return;

  const msg = event.message;
  const yaw = msg.pose.z;
  const steering = globalVars.steering ?? 0;

  const pos = applyOffset(msg.pose.x, msg.pose.y, yaw);

  const ack = computeAckermann(steering);

  function worldPos(local: { x: number; y: number }) {
    const rot = rotate2D(local.x, local.y, yaw);
    return {
      x: pos.x + rot.x,
      y: pos.y + rot.y,
    };
  }

  const markers: Marker[] = [];

  // === MONOCOQUE ===
  markers.push(
    buildRosMarker({
      header: msg.header,
      ns: "Vehicle",
      id: 0,
      type: MarkerTypes.MESH,
      pose: {
        position: { x: pos.x, y: pos.y, z: 0 },
        orientation: yawToQuat(yaw),
      },
      scale: { x: 1, y: 1, z: 1 },
      mesh_resource: MESH.monocoque,
    }),
  );

  // === REAR (no steering) ===
  const rearPos = pos;
  markers.push(
    buildRosMarker({
      header: msg.header,
      ns: "Vehicle",
      id: 1,
      type: MarkerTypes.MESH,
      pose: {
        position: { x: rearPos.x, y: rearPos.y, z: 0 },
        orientation: yawToQuat(yaw),
      },
      scale: { x: 1, y: 1, z: 1 },
      mesh_resource: MESH.rear,
    }),
  );

  // === FRONT LEFT ===
  const flPos = pos;
  markers.push(
    buildRosMarker({
      header: msg.header,
      ns: "Vehicle",
      id: 2,
      type: MarkerTypes.MESH,
      pose: {
        position: { x: flPos.x, y: flPos.y, z: 0 },
        orientation: yawToQuat(yaw + ack.left),
      },
      scale: { x: 1, y: 1, z: 1 },
      mesh_resource: MESH.fl,
    }),
  );

  // === FRONT RIGHT ===
  const frPos = pos;
  markers.push(
    buildRosMarker({
      header: msg.header,
      ns: "Vehicle",
      id: 3,
      type: MarkerTypes.MESH,
      pose: {
        position: { x: frPos.x, y: frPos.y, z: 0 },
        orientation: yawToQuat(yaw + ack.right),
      },
      scale: { x: 1, y: 1, z: 1 },
      mesh_resource: MESH.fr,
      action: 0
    }),
  );

  return {markers: markers};
}

