import { Input, Message } from "./types";

export const inputs = ["/viz/slam/path_corrected"];
export const output = "/userscripts/cog/path";

type Path = Message<"nav_msgs/Path">;

// ==== 🔧 DISTANCE CoG → LiDAR (meters) ====
const distanceCogToLidar = 1.2;

// ==== Quaternion → yaw ====
function getYaw(q: { x: number; y: number; z: number; w: number }) {
  return Math.atan2(
    2.0 * (q.w * q.z + q.x * q.y),
    1.0 - 2.0 * (q.y * q.y + q.z * q.z),
  );
}

// ==== Transform path ====
function transformPath(path: Path): Path {
  const transformedPoses = path.poses.map((pose) => {
    const p = pose.pose.position;
    const q = pose.pose.orientation;

    const yaw = getYaw(q);

    return {
      ...pose,
      pose: {
        ...pose.pose,
        position: {
          x: p.x - distanceCogToLidar * Math.cos(yaw),
          y: p.y - distanceCogToLidar * Math.sin(yaw),
          z: p.z,
        },
      },
    };
  });

  return {
    ...path,
    header: {
      ...path.header,
      frame_id: "world", // adjust if needed
    },
    poses: transformedPoses,
  };
}

// ==== Main ====
export default function transform_path(
  event: Input<"/viz/slam/path_corrected">,
): Path {
  return transformPath(event.message);
}
